#include <stdio.h>
#include <stdlib.h>

#define MAXN 10005
#define MAXM 40005
#define INF 1000000000000000000LL

typedef struct {
    int to, w, id, next;
} Edge;

Edge edges[MAXM];
int head[MAXN], ecnt = 0;

void addEdge(int u, int v, int w, int id) {
    edges[ecnt].to = v;
    edges[ecnt].w = w;
    edges[ecnt].id = id;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

int N, M;
int state[MAXN];
int parent[MAXN];
int parentW[MAXN];
long long distRoot[MAXN];
int cycleId[MAXN];

typedef struct {
    int *vertices;
    int size;
    long long len;
} Cycle;

Cycle cycles[MAXN];
int cycleCnt = 0;
int tempVertices[MAXN];

void dfs(int u, int pe) {
    state[u] = 1;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        if (edges[e].id == pe) continue;
        int v = edges[e].to;
        if (state[v] == 0) {
            parent[v] = u;
            parentW[v] = edges[e].w;
            distRoot[v] = distRoot[u] + edges[e].w;
            dfs(v, edges[e].id);
        } else if (state[v] == 1) {
            int curr = u;
            long long len = edges[e].w;
            int cnt = 0;
            while (curr != v) {
                tempVertices[cnt++] = curr;
                len += parentW[curr];
                curr = parent[curr];
            }
            tempVertices[cnt++] = v;
            int cid = cycleCnt++;
            cycles[cid].size = cnt;
            cycles[cid].len = len;
            cycles[cid].vertices = (int*)malloc(cnt * sizeof(int));
            for (int i = 0; i < cnt; i++) {
                cycles[cid].vertices[i] = tempVertices[i];
                cycleId[tempVertices[i]] = cid;
            }
        }
    }
    state[u] = 2;
}

typedef struct {
    long long d;
    int v;
} Node;

Node heap[MAXM * 2];
int heapSize = 0;

void heapPush(long long d, int v) {
    int i = heapSize++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].d <= d) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].d = d;
    heap[i].v = v;
}

Node heapPop() {
    Node ret = heap[0];
    heapSize--;
    if (heapSize > 0) {
        Node temp = heap[heapSize];
        int i = 0;
        while (1) {
            int l = 2 * i + 1;
            int r = 2 * i + 2;
            int smallest = i;
            if (l < heapSize && heap[l].d < temp.d) smallest = l;
            if (r < heapSize && heap[r].d < temp.d) smallest = r;
            if (smallest == i) break;
            heap[i] = heap[smallest];
            i = smallest;
        }
        heap[i] = temp;
    }
    return ret;
}

long long dist[MAXN];

void dijkstra(int src) {
    for (int i = 1; i <= N; i++) dist[i] = INF;
    dist[src] = 0;
    heapSize = 0;
    heapPush(0, src);
    while (heapSize > 0) {
        Node cur = heapPop();
        int u = cur.v;
        long long d = cur.d;
        if (d != dist[u]) continue;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            long long nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heapPush(nd, v);
            }
        }
    }
}

int main() {
    scanf("%d %d", &N, &M);
    for (int i = 1; i <= N; i++) {
        head[i] = -1;
        cycleId[i] = -1;
    }
    for (int i = 1; i <= M; i++) {
        int A, B, C;
        scanf("%d %d %d", &A, &B, &C);
        addEdge(A, B, C, i);
        addEdge(B, A, C, i);
    }
    for (int i = 1; i <= N; i++) {
        if (state[i] == 0) {
            distRoot[i] = 0;
            dfs(i, -1);
        }
    }
    int K;
    scanf("%d", &K);
    long long minDist[MAXN];
    for (int q = 0; q < K; q++) {
        int X, T;
        scanf("%d %d", &X, &T);
        dijkstra(X);
        for (int c = 0; c < cycleCnt; c++) {
            minDist[c] = INF;
        }
        for (int v = 1; v <= N; v++) {
            int cid = cycleId[v];
            if (cid != -1 && dist[v] < minDist[cid]) {
                minDist[cid] = dist[v];
            }
        }
        long long ans = INF;
        for (int c = 0; c < cycleCnt; c++) {
            if (cycles[c].len >= T && minDist[c] < INF) {
                long long val = cycles[c].len + 2 * minDist[c];
                if (val < ans) ans = val;
            }
        }
        if (ans == INF) printf("-1\n");
        else printf("%lld\n", ans);
    }
    return 0;
}
